        "article": "Arts. 36 a 38 da Lei nº 10.257/2001 (Estatuto da Cidade)",
        "textSnippet": "Estatuto da Cidade (Lei 10.257/01): EIV NÃO substitui o EIA/RIMA (Art. 38)! Documentos do EIV são públicos. Plano Diretor = obrigatório para > 20.000 habitantes."
