    "difficultyLevel": 2,
    "originType": "AUTORAL_PROFESSOR",
    "statement": "Empresa destrói mata ciliar nativa; anos depois, após sentença judicial, consegue reflorestar a área degradada, mas a floresta levou 12 anos sem prestar serviços ecossistêmicos à coletividade. Além da obrigação de recuperar a área (in natura), cabe indenização pelo período em que o ambiente ficou degradado?",
    "options": [
      {
        "letter": "A",
        "text": "Recuperada a área degradada 10 anos depois, extingue-se integralmente qualquer dever de indenizar em dinheiro pelo período perdido, com preservação da imprescritibilidade da pretensão voltada à reparação do dano ecológico."
      },
      {
        "letter": "B",
        "text": "Sim, o STJ admite expressamente a cumulação tríplice da obrigação de fazer, da indenização pelo dano ambiental interino/intermediário ou dano residual, bem como do dano moral coletivo ambiental."
      },
      {
        "letter": "C",
        "text": "A Súmula 629 proíbe cumular obrigação de recompor a floresta com pagamento de indenização pecuniária por configurar bis in idem, observada a competência comum material dos entes federativos para fiscalização e proteção."
      },
      {
        "letter": "D",
        "text": "Apenas o dano moral individual de vizinho específico é admitido no Brasil, nunca o dano moral coletivo ambiental, sujeita ao regime constitucional de bem de uso comum do povo e equidade intergeracional."
      }
    ],
    "correctAnswer": "B",
    "justification": "Súmula 629 STJ: recomposição in natura + indenização em dinheiro (dano interino, dano residual e dano moral coletivo) são perfeitamente cumuláveis!",
    "whyWrong": [
      {
        "letter": "A",
        "explanation": "A reparação in natura tardia não apaga o déficit ecológico sofrido pela sociedade durante os anos de degradação (dano ambiental interino/intermediário)!"
      },
      {
        "letter": "C",
        "explanation": "A Súmula 629 do STJ foi editada justamente para afirmar a plena POSSIBILIDADE de cumulação entre obrigação de fazer/não fazer e indenizar!"
      },
      {
        "letter": "D",
        "explanation": "O STJ admite amplamente o dano moral coletivo em matéria ambiental cumulado com a recomposição ecológica."
      }
    ],
