        "code": "CF/88 / Lei nº 6.938/1981",
        "article": "Súmula 629 do STJ e Jurisprudência sobre Dano Interino/Residual",
        "textSnippet": "Súmula 629 STJ: recomposição in natura + indenização em dinheiro (dano interino, dano residual e dano moral coletivo) são perfeitamente cumuláveis!"
